I have found that following one line patch workarounds this:

diff --git a/dlls/user32/misc.c b/dlls/user32/misc.c
index 6333fcb48b4..773abf77f97 100644
--- a/dlls/user32/misc.c
+++ b/dlls/user32/misc.c
@@ -520,7 +520,7 @@ BOOL WINAPI GetPointerType(UINT32 id, POINTER_INPUT_TYPE *type)
         return FALSE;
     }

-    *type = PT_MOUSE;
+    *type = PT_TOUCH;
     return TRUE;
 }
